//! Environment attestation — the proof, produced by the checker.
//!
//! An attestation is only worth anything if it is generated by the same code that
//! enforces the property. If `jhol verify` and `jhol attest` were different code
//! paths, the attestation would eventually describe a tree nobody checked. So this
//! module records exactly what the verifier observes, and verification re-runs the
//! verifier rather than trusting the file.
//!
//! Content is deterministic: sorted keys, no timestamps. Two machines with the same
//! environment produce byte-identical attestations, which makes them diffable and
//! cacheable — and makes "did this change?" an answerable question.

use std::collections::BTreeMap;
use std::path::Path;

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize, Default)]
pub struct Attestation {
    #[serde(default = "one")]
    pub schema: u32,
    /// SHA-256 of package.json — the intent.
    pub manifest: String,
    /// Tree path -> installed version, sorted.
    #[serde(default)]
    pub packages: BTreeMap<String, String>,
    /// Model name -> aggregate digest, sorted.
    #[serde(default)]
    pub models: BTreeMap<String, String>,
    /// Host axes at the time of the attestation.
    #[serde(default)]
    pub axes: BTreeMap<String, String>,
    /// Resolver/lockfile digest, so a lockfile edit is visible.
    pub lockfile: String,
}

fn one() -> u32 {
    1
}

pub const ATTESTATION_PATH: &str = ".jhol/attestation.json";

fn sha256_file(path: &Path) -> Option<String> {
    use sha2::{Digest, Sha256};
    use std::io::Read;
    let mut f = std::fs::File::open(path).ok()?;
    let mut hasher = Sha256::new();
    let mut buf = vec![0u8; 1 << 20];
    loop {
        let n = f.read(&mut buf).ok()?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Some(format!("{:x}", hasher.finalize()))
}

fn sha256_bytes(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    let mut h = Sha256::new();
    h.update(bytes);
    format!("{:x}", h.finalize())
}

impl Attestation {
    pub fn path(root: &Path) -> std::path::PathBuf {
        root.join(ATTESTATION_PATH)
    }

    /// Build from the current state of the project. Uses the same verifier the CLI
    /// gate uses; an unverifiable tree produces an error rather than a certificate.
    pub fn build(root: &Path) -> Result<Self, String> {
        let state = crate::tree_state::verify_tree(root);
        if !state.is_match() {
            return Err(format!(
                "refusing to attest a tree that does not match the lockfile: {}",
                state.describe()
            ));
        }
        let manifest = crate::lockfile::read_resolved_from_dir(root)
            .map(|m| {
                let mut sorted: Vec<(String, String)> = m.into_iter().collect();
                sorted.sort();
                sha256_bytes(sorted.iter().map(|(k, v)| format!("{k}@{v}\n")).collect::<String>().as_bytes())
            })
            .unwrap_or_else(|| "none".to_string());

        let packages: BTreeMap<String, String> = crate::lockfile::read_resolved_from_dir(root)
            .unwrap_or_default()
            .into_iter()
            .collect();

        let models: BTreeMap<String, String> = crate::model_lock::ModelLock::load(root)
            .map(|lock| {
                lock.models
                    .into_iter()
                    .map(|(name, entry)| {
                        let mut pins: Vec<String> = entry
                            .files
                            .iter()
                            .map(|f| format!("{}:{}", f.path, f.sha256))
                            .collect();
                        pins.sort();
                        (name, sha256_bytes(pins.join("\n").as_bytes()))
                    })
                    .collect()
            })
            .unwrap_or_default();

        let host = crate::axes::HostAxes::detect();
        let mut axes: BTreeMap<String, String> = BTreeMap::new();
        axes.insert("os".into(), host.os);
        axes.insert("arch".into(), host.arch);
        axes.insert("libc".into(), host.libc.to_string());
        if let Some(py) = host.python {
            axes.insert("python".into(), py);
        }
        if let Some(driver) = host.cuda_driver {
            axes.insert("cuda_driver".into(), driver);
        }

        let lockfile = ["package-lock.json", "npm-shrinkwrap.json", "jhol-lock.json"]
            .iter()
            .map(|n| root.join(n))
            .find(|p| p.exists())
            .and_then(|p| sha256_file(&p))
            .unwrap_or_else(|| "none".to_string());

        let _ = crate::lockfile::read_package_json_deps(&root.join("package.json"));
        let manifest_file = sha256_file(&root.join("package.json")).unwrap_or_else(|| "none".into());
        let _ = manifest;

        Ok(Attestation {
            schema: 1,
            manifest: manifest_file,
            packages,
            models,
            axes,
            lockfile,
        })
    }

    pub fn save(&self, root: &Path) -> std::io::Result<()> {
        let path = Self::path(root);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let tmp = path.with_extension("tmp");
        std::fs::write(&tmp, serde_json::to_vec_pretty(self)?)?;
        std::fs::rename(&tmp, &path)
    }

    pub fn load(root: &Path) -> Option<Self> {
        serde_json::from_str(&std::fs::read_to_string(Self::path(root)).ok()?).ok()
    }

    /// Verify by rebuilding and comparing — the only honest form. `Ok(())` means the
    /// project still is what was attested.
    pub fn verify(&self, root: &Path) -> Result<(), String> {
        let now = Self::build(root)?;
        if &now == self {
            Ok(())
        } else {
            let mut diffs = Vec::new();
            if now.manifest != self.manifest {
                diffs.push("package.json changed".to_string());
            }
            if now.lockfile != self.lockfile {
                diffs.push("lockfile changed".to_string());
            }
            if now.packages != self.packages {
                diffs.push("resolved packages changed".to_string());
            }
            if now.models != self.models {
                diffs.push("model pins changed".to_string());
            }
            if now.axes != self.axes {
                diffs.push("host axes changed".to_string());
            }
            Err(format!(
                "attestation does not match: {}",
                if diffs.is_empty() {
                    "unknown difference".to_string()
                } else {
                    diffs.join(", ")
                }
            ))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn project(dir: &Path) {
        std::fs::create_dir_all(dir.join("node_modules/a")).unwrap();
        std::fs::write(dir.join("package.json"), r#"{"name":"p","dependencies":{"a":"^1"}}"#).unwrap();
        std::fs::write(
            dir.join("package-lock.json"),
            r#"{"lockfileVersion":3,"packages":{"":{"name":"p"},"node_modules/a":{"version":"1.0.0"}}}"#,
        )
        .unwrap();
        std::fs::write(
            dir.join("node_modules/a/package.json"),
            r#"{"name":"a","version":"1.0.0"}"#,
        )
        .unwrap();
    }

    #[test]
    fn attests_a_good_tree_and_detects_change() {
        let tmp = tempfile::tempdir().unwrap();
        project(tmp.path());
        let att = Attestation::build(tmp.path()).unwrap();
        assert_eq!(att.packages.get("a").map(String::as_str), Some("1.0.0"));
        att.save(tmp.path()).unwrap();
        let loaded = Attestation::load(tmp.path()).unwrap();
        assert_eq!(loaded, att);
        assert_eq!(loaded.verify(tmp.path()), Ok(()));

        // A manifest edit must invalidate it.
        std::fs::write(tmp.path().join("package.json"), r#"{"name":"p","version":"2"}"#).unwrap();
        let err = loaded.verify(tmp.path()).unwrap_err();
        assert!(err.contains("package.json changed"), "{err}");
    }

    #[test]
    fn refuses_to_attest_an_unverifiable_tree() {
        let tmp = tempfile::tempdir().unwrap();
        project(tmp.path());
        std::fs::write(tmp.path().join("node_modules/a/package.json"), r#"{"name":"a","version":"9.9.9"}"#).unwrap();
        let err = Attestation::build(tmp.path()).unwrap_err();
        assert!(err.contains("does not match"), "{err}");
    }

    #[test]
    fn attestation_is_deterministic() {
        let tmp = tempfile::tempdir().unwrap();
        project(tmp.path());
        let a = Attestation::build(tmp.path()).unwrap();
        let b = Attestation::build(tmp.path()).unwrap();
        assert_eq!(
            serde_json::to_vec(&a).unwrap(),
            serde_json::to_vec(&b).unwrap(),
            "no timestamps, sorted keys: two runs must be byte-identical"
        );
    }
}
